& \geq  1 -  \delta  - 2  \sqrt{ (1-\mathrm{F}(\rho,\rho'))^{1/2}}  . \quad \mbox{(Claim~\ref{claim:2} and Eq.~\eqref{eq:probonrho'})}
\end{align*}

